  ('pradeep-shettar', $pvg$Pradeep Shettar$pvg$, $pvg$harihara$pvg$, $pvg$Testimonial by Pradeep Shettar$pvg$, $pvg$kind and knowledgeable persons.$pvg$, '/legacy/testimonials/pradeep-shettar-proof.jpg', $pvg$Proof from Pradeep Shettar$pvg$, 'https://www.purevedicgems.com/testimonial/pradeep-shettar/', 5, 'approved', true, false, 174, '2023-12-26T00:00:00Z'),
  ('satin-jamgotre', $pvg$Satin Jamgotre$pvg$, $pvg$London$pvg$, $pvg$Testimonial by Satin Jamgotre$pvg$, $pvg$Excellent customer service .. very helpful.. very happy with my product .Always very helpful .. Thankyou Satin .$pvg$, '/legacy/testimonials/satin-jamgotre-proof.jpg', $pvg$Proof from Satin Jamgotre$pvg$, 'https://www.purevedicgems.com/testimonial/satin-jamgotre/', 5, 'approved', true, false, 175, '2023-12-26T00:00:00Z'),
  ('monica-lala', $pvg$Monica lala$pvg$, $pvg$Sector 5$pvg$, $pvg$Testimonial by Monica lala$pvg$, $pvg$Thank you so much for the product is so genuine and your service is also very proactive.. your team helped me to shortlist the stone as per budget and requirements.. Your team connect 1-1 understand my requirement and then helped me to book.. i was very skeptical but the product i received is very good quality.. Over all 10/10 service$pvg$, '/legacy/testimonials/monica-lala-proof.jpg', $pvg$Proof from Monica lala$pvg$, 'https://www.purevedicgems.com/testimonial/monica-lala/', 5, 'approved', true, false, 176, '2024-02-23T00:00:00Z'),
  ('bhushan-r-balpande', $pvg$Bhushan R. Balpande$pvg$, $pvg$Warthi$pvg$, $pvg$Testimonial by Bhushan R. Balpande$pvg$, $pvg$Good better best quality than any one site... Give Good result on wear gemstone .. my favourite site.. here got reasonable rate of gemstone other than site same quality.. thanking you ..pure Vedic gems Now,I will buy red Ruby after some days$pvg$, '/legacy/testimonials/bhushan-r-balpande-proof.jpg', $pvg$Proof from Bhushan R. Balpande$pvg$, 'https://www.purevedicgems.com/testimonial/bhushan-r-balpande/', 5, 'approved', true, false, 177, '2024-02-23T00:00:00Z'),
  ('moumita', $pvg$Moumita$pvg$, $pvg$Old Airport$pvg$, $pvg$Testimonial by Moumita$pvg$, $pvg$Good Genuine products, got on time.$pvg$, '/legacy/testimonials/moumita-proof.jpg', $pvg$Proof from Moumita$pvg$, 'https://www.purevedicgems.com/testimonial/moumita/', 5, 'approved', true, false, 178, '2024-02-27T00:00:00Z'),
  ('anurag', $pvg$Anurag$pvg$, $pvg$U.P$pvg$, $pvg$Testimonial by Anurag$pvg$, $pvg$Good services and well behaved culture.$pvg$, '/legacy/testimonials/anurag-proof.jpg', $pvg$Proof from Anurag$pvg$, 'https://www.purevedicgems.com/testimonial/anurag/', 5, 'approved', true, false, 179, '2024-04-21T00:00:00Z'),
  ('avinash', $pvg$Avinash$pvg$, $pvg$Australia$pvg$, $pvg$Testimonial by Avinash$pvg$, $pvg$Hi there, Reaching out to provide great customer service being provided by Pure Vedic Gems Team. He has been very helpful in keeping me informed of my rings and what state the order is. Also sharing pictures which provide assurance that my order is progressing as per my satisfaction. This is a great customer service and want to thank Pure Vedic Gems Team. I look forward to receiving the rings. Many thanks Kind Regards, Avinash$pvg$, '/legacy/testimonials/avinash-proof.jpg', $pvg$Proof from Avinash$pvg$, 'https://www.purevedicgems.com/testimonial/avinash/', 5, 'approved', true, false, 180, '2024-04-23T00:00:00Z'),
  ('will-davis', $pvg$Will Davis$pvg$, $pvg$USA$pvg$, $pvg$Testimonial by Will Davis$pvg$, $pvg$Thank you very much Pure Vedic Gems. My hessonite silver pendant is very beautiful. The gem is translucent and unheated which makes it good for Rahu, the ascending lunar node in Vedic astrology. I feel very blessed to have this healing gemstone.$pvg$, '/legacy/testimonials/will-davis-proof.jpg', $pvg$Proof from Will Davis$pvg$, 'https://www.purevedicgems.com/testimonial/will-davis/', 5, 'approved', true, false, 181, '2024-04-27T00:00:00Z'),
  ('ashok-kumar-pujari', $pvg$Ashok kumar pujari$pvg$, $pvg$BARGARH$pvg$, $pvg$Testimonial by Ashok kumar pujari$pvg$, $pvg$Gemstones supplied by pure vedic gemstones are genuine certified and sare astrologically effective.. The staff headed by Mr.Vikas Mehra are cooperative helpful and well behaved. I recommend to purchase gemstones from pure vedic gemstones which is one of the oldest gemstones company. I wish wide popularity of pure vedic gems.$pvg$, '/legacy/testimonials/ashok-kumar-pujari-proof.jpg', $pvg$Proof from Ashok kumar pujari$pvg$, 'https://www.purevedicgems.com/testimonial/ashok-kumar-pujari/', 5, 'approved', true, false, 182, '2024-05-03T00:00:00Z'),
  ('will-davis-2', $pvg$Will Davis$pvg$, $pvg$USA$pvg$, $pvg$Testimonial by Will Davis$pvg$, $pvg$I am extremely happy with the Vedic astrology white sapphire ring and ruby pendant I purchased from Pure Vedic Gems. I am also happy with the puja energization done for these gems. The energy I feel from these gems is very sublime, blissful, and life supporting.$pvg$, '/legacy/testimonials/will-davis-2-proof.jpg', $pvg$Proof from Will Davis$pvg$, 'https://www.purevedicgems.com/testimonial/will-davis-2/', 5, 'approved', true, false, 183, '2024-06-08T00:00:00Z'),
  ('rajneesh', $pvg$Rajneesh$pvg$, $pvg$Canada$pvg$, $pvg$Testimonial by Rajneesh$pvg$, $pvg$My personal experience with Pure Vedic Gems is way above expectations. My man, pure vedic gems along with his entire team very professional, thoughtful, and personable. It took me approximately 4 weeks from start to finish, which included help with choosing the right stone, design of the ring and writing this thank you note with immense pleasure, after wearing I would recommend them from the bottom of my heart. Thank you, Pure Vedic gems team along with Vikasjee, and the entire staff!! Take care of yourselves, and Godspeed!!!$pvg$, '/legacy/testimonials/rajneesh-proof.jpg', $pvg$Proof from Rajneesh$pvg$, 'https://www.purevedicgems.com/testimonial/rajneesh/', 5, 'approved', true, false, 184, '2024-06-14T00:00:00Z'),
  ('hemanth', $pvg$Hemanth$pvg$, $pvg$USA$pvg$, $pvg$Testimonial by Hemanth$pvg$, $pvg$Purevedic gems fulfilled my request for 17 mukhi rudraksha and other mukhi rudraksha. Particularly you took almost care in preparing the order fulfillment and the energization process was also very much appreciated. Where I was allowed to be part of the energization process. Overall from ordering to receiving the order I couldnâ€™t have been more happier. Thank you for your help!! I am sure there will be many more visits in the future. Thank you again!$pvg$, '/legacy/testimonials/hemanth-proof.jpg', $pvg$Proof from Hemanth$pvg$, 'https://www.purevedicgems.com/testimonial/hemanth/', 5, 'approved', true, false, 185, '2024-06-14T00:00:00Z'),
  ('joycez', $pvg$JoyceZ$pvg$, $pvg$USA$pvg$, $pvg$Testimonial by JoyceZ$pvg$, $pvg$Love the Hessonite Ring! Well made, beautiful authentic gemstone, clear, nicely cut and well made. Good customer service with Pure Vedic Gems Team. Fast shipping. Would definitely purchase again from Pure Vedic Gems. Thank you!$pvg$, '/legacy/testimonials/joycez-proof.jpg', $pvg$Proof from JoyceZ$pvg$, 'https://www.purevedicgems.com/testimonial/joycez/', 5, 'approved', true, false, 186, '2024-12-10T00:00:00Z'),
  ('sreejith', $pvg$sreejith$pvg$, $pvg$Gulf$pvg$, $pvg$Testimonial by sreejith$pvg$, $pvg$The product was fully energised and shipped as per order. Happy with the customer service and product$pvg$, '/legacy/testimonials/sreejith-proof.jpeg', $pvg$Proof from sreejith$pvg$, 'https://www.purevedicgems.com/testimonial/sreejith/', 5, 'approved', true, false, 187, '2025-06-13T00:00:00Z'),
  ('harsh-yadav', $pvg$Harsh Yadav$pvg$, $pvg$Modern Apartment$pvg$, $pvg$Testimonial by Harsh Yadav$pvg$, $pvg$Authentic rudraksha and gems. I attended the Praan pratishtha of my rudrakshas personally. Glad that I found Pure Vedic gems as it is difficult to find authentic rudraksha and gems.$pvg$, '/legacy/testimonials/harsh-yadav-proof.jpeg', $pvg$Proof from Harsh Yadav$pvg$, 'https://www.purevedicgems.com/testimonial/harsh-yadav/', 5, 'approved', true, false, 188, '2025-06-13T00:00:00Z'),
  ('ratish-kumar', $pvg$Ratish Kumar$pvg$, $pvg$Chhattisgarh$pvg$, $pvg$Testimonial by Ratish Kumar$pvg$, $pvg$At first, I was apprehensive about purchasing gemstones online. But in the end, I received a link to a purevedic gem that made it very simple for the customer service representatives to choose the best quality rudraksha and emerald. They shared all of the pictures and videos of the stone and rudraksha on WhatsApp and helped me choose the design of the ring and measure my ring size correctly. I received a ring and rudraksha along with a real quality certificate in 4 to 5 days. Thanks to Purevedic gem and customer service staff$pvg$, '/legacy/testimonials/ratish-kumar-proof.jpeg', $pvg$Proof from Ratish Kumar$pvg$, 'https://www.purevedicgems.com/testimonial/ratish-kumar/', 5, 'approved', true, false, 189, '2025-06-13T00:00:00Z'),
  ('vidhya', $pvg$Vidhya$pvg$, $pvg$Bangalore$pvg$, $pvg$Testimonial by Vidhya$pvg$, $pvg$Very good quality. Much satisfied. Friendly staff$pvg$, '/legacy/testimonials/vidhya-proof.jpeg', $pvg$Proof from Vidhya$pvg$, 'https://www.purevedicgems.com/testimonial/vidhya/', 5, 'approved', true, false, 190, '2025-06-13T00:00:00Z'),
  ('vijay-krishna-agrawal', $pvg$Vijay Krishna Agrawal$pvg$, $pvg$GS Road$pvg$, $pvg$Testimonial by Vijay Krishna Agrawal$pvg$, $pvg$Genuine and good product. Representative was very supportive and cooperative$pvg$, '/legacy/testimonials/vijay-krishna-agrawal-proof.jpeg', $pvg$Proof from Vijay Krishna Agrawal$pvg$, 'https://www.purevedicgems.com/testimonial/vijay-krishna-agrawal/', 5, 'approved', true, false, 191, '2025-06-13T00:00:00Z'),
  ('aurobinda-das', $pvg$Aurobinda das$pvg$, $pvg$Odisha$pvg$, $pvg$Testimonial by Aurobinda das$pvg$, $pvg$Very good experience$pvg$, '/legacy/testimonials/aurobinda-das-proof.jpg', $pvg$Proof from Aurobinda das$pvg$, 'https://www.purevedicgems.com/testimonial/aurobinda-das/', 5, 'approved', true, false, 192, '2025-06-13T00:00:00Z'),
  ('dodik', $pvg$Dodik$pvg$, $pvg$Sweden$pvg$, $pvg$Testimonial by Dodik$pvg$, $pvg$Great communication, wonderful choice of stones and ring designs, the ring looks gorgeous, the rudrakshis are amazing. We are very pleased and will absolutely be back again!$pvg$, '/legacy/testimonials/dodik-proof.jpg', $pvg$Proof from Dodik$pvg$, 'https://www.purevedicgems.com/testimonial/dodik/', 5, 'approved', true, false, 193, '2025-06-13T00:00:00Z'),
  ('suchitra-b-m', $pvg$Suchitra B M$pvg$, $pvg$Belaum$pvg$, $pvg$Testimonial by Suchitra B M$pvg$, $pvg$Dear Vikas Mehra Sir , I would like to thank you very much for providing me with the best Gemstones at reasonable price. The quality is best for the price quoted. Best thing is the work of the kaarigar in the setting in stones in rings, amazingly beautiful work. I would also thank your team sir for the best support and services and the guidance provided by your team in analysing kundali and giving the best advice. I look to purchase more gems for my family members and by Gods grace will purchase soon. I am associated to purevedic gems since 2022 and they have gained my trust. Thank you once again for all the support and continue the good work. May God bless the team for their good work.$pvg$, '/legacy/testimonials/suchitra-b-m-proof.jpg', $pvg$Proof from Suchitra B M$pvg$, 'https://www.purevedicgems.com/testimonial/suchitra-b-m/', 5, 'approved', true, false, 194, '2025-06-13T00:00:00Z')
ON CONFLICT (slug) DO UPDATE SET
  name = EXCLUDED.name,
  location = EXCLUDED.location,
  message = EXCLUDED.message,
  proof_image_url = EXCLUDED.proof_image_url,
  proof_alt = EXCLUDED.proof_alt,
  source_url = EXCLUDED.source_url,
  rating = EXCLUDED.rating,
  status = EXCLUDED.status,
  is_active = EXCLUDED.is_active,
  sort_order = EXCLUDED.sort_order,
  published_at = EXCLUDED.published_at,
  updated_at = NOW();

SELECT COUNT(*) AS total_testimonials FROM testimonials;